import sys


def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    budget = int(data[1])
    par = [0] * (n + 1)
    for i in range(2, n + 1):
        par[i] = int(data[i])
    depth = [0] * (n + 1)
    hi = 0
    for i in range(2, n + 1):
        d = depth[par[i]] + 1
        depth[i] = d
        if d > hi:
            hi = d

    def saves(k: int) -> int:
        h = [0] * (n + 1)
        cnt = 0
        for v in range(n, 1, -1):
            hv = h[v]
            if hv == k:
                cnt += 1
                if cnt > budget:
                    return cnt
            else:
                p = par[v]
                if hv + 1 > h[p]:
                    h[p] = hv + 1
        return cnt + 1

    lo = 0
    while lo < hi:
        mid = (lo + hi) // 2
        if saves(mid) <= budget:
            hi = mid
        else:
            lo = mid + 1
    print(lo)


main()
